\newcommand{\dneg}{\mathrm{dneg}}
\newcommand{\preFixed}{\operatorname{preFixed}}
\newcommand{\postFixed}{\operatorname{postFixed}}
\newcommand{\Opens}{\operatorname{Opens}}
\newcommand{\Sub}{\operatorname{Sub}}
\newcommand{\himp}{\Rightarrow}
\newcommand{\meet}{\wedge}
\newcommand{\join}{\vee}
