"""Exercise the nucleus laws + fixed points on several frames of down-sets."""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List, Set

Elt = FrozenSet[int]

def downsets(points: List[int], leq: Callable[[int, int], bool]) -> List[Elt]:
    out: List[Elt] = []
    for r in range(len(points) + 1):
        for combo in combinations(points, r):
            s = set(combo)
            if all(p in s for q in s for p in points if leq(p, q)):
                out.append(frozenset(s))
    return out

def himp(E: List[Elt], a: Elt, c: Elt) -> Elt:
    res: Set[int] = set()
    for x in E:
        if (a & x) <= c:
            res |= x
    return frozenset(res)

def compl(E: List[Elt], a: Elt) -> Elt:
    return himp(E, a, frozenset())

def dneg(E: List[Elt], a: Elt) -> Elt:
    return compl(E, compl(E, a))

def main() -> None:
    pts = [0, 1, 2, 3]
    edges = {(0, 1), (0, 2), (1, 3), (2, 3), (0, 3)}
    leq = lambda p, q: p == q or (p, q) in edges
    E = downsets(pts, leq)
    top, bot = frozenset(pts), frozenset()
    # nucleus laws
    assert all(a <= dneg(E, a) for a in E)                          # le_dneg
    assert all(dneg(E, dneg(E, a)) == dneg(E, a) for a in E)        # dneg_idem
    assert all(dneg(E, a & b) == dneg(E, a) & dneg(E, b)
               for a in E for b in E)                               # dneg_inf
    assert dneg(E, bot) == bot and dneg(E, top) == top              # bounds
    # fixed points
    pre = [x for x in E if dneg(E, x) <= x]
    post = [x for x in E if x <= dneg(E, x)]
    lfp = top
    for x in pre:
        lfp &= x
    gfp = bot
    for x in post:
        gfp |= x
    assert lfp == bot and gfp == top                               # lfp/gfp
    regs = [a for a in E if dneg(E, a) == a]
    print("regular elements:", [set(a) for a in regs])
    print("lfp(dneg) =", set(lfp), " gfp(dneg) =", set(gfp))
    print("All nucleus + fixed-point laws verified.")

if __name__ == "__main__":
    main()

